"""Scan the session transcript for ASSISTANT TEXT blocks (never tool_use input,
never tool results) containing any of the needles; print timestamp + a window.
Read-only."""
import json
import sys

T = r"C:/Users/jeetm/.claude/projects/c--Users-jeetm-Github-stock-picks-app/433f0dcd-be9f-40ae-8e1a-d85ed86ac2e0.jsonl"
NEEDLES = sys.argv[1:] or ["every article from 2025", "10,642"]
hits = 0
with open(T, "r", encoding="utf-8", errors="replace") as fh:
    for ln, line in enumerate(fh, 1):
        if '"assistant"' not in line:
            continue
        if not any(n in line for n in NEEDLES):
            continue
        try:
            e = json.loads(line)
        except Exception:
            continue
        if e.get("type") != "assistant":
            continue
        for blk in (e.get("message") or {}).get("content") or []:
            if not isinstance(blk, dict) or blk.get("type") != "text":
                continue
            txt = blk.get("text") or ""
            for n in NEEDLES:
                i = txt.find(n)
                if i >= 0:
                    hits += 1
                    print("line %d ts %s needle %r" % (ln, e.get("timestamp"), n))
                    print("   ..." + txt[max(0, i - 400): i + 400].replace("\n", " ") + "...")
print("assistant-text hits:", hits)
